def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if len(alive_opponents) == 0:
        base = DAILY_SALARY * 0.28
        if no_water_days >= 1 or hp <= 3:
            base = DAILY_SALARY * 0.55
        return float(min(budget, max(0.0, base)))

    total_players = 1 + len(alive_opponents)
    tight_supply = supply <= total_players * WATER_REQ
    very_tight = supply <= max(WATER_REQ, (total_players - 1) * WATER_REQ)

    highest_prev_bid = 0.0
    avg_prev_bid = 0.0
    count_prev = 0
    rich_aggressive = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        prev_bid = 0.0
        if prev and prev.get('bid') is not None:
            prev_bid = float(prev.get('bid', 0.0))
            if prev_bid > highest_prev_bid:
                highest_prev_bid = prev_bid
            avg_prev_bid += prev_bid
            count_prev += 1
        if opp.get('budget', 0.0) >= 140 and prev_bid >= 120:
            rich_aggressive += 1

    if count_prev > 0:
        avg_prev_bid = avg_prev_bid / count_prev

    urgency = 0
    if hp <= 2 or no_water_days >= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency == 3:
        target = max(0.92 * DAILY_SALARY, highest_prev_bid + 4.0)
        if very_tight:
            target = max(target, 0.98 * DAILY_SALARY)
    elif urgency == 2:
        if highest_prev_bid >= 150:
            target = 0.58 * DAILY_SALARY if not tight_supply else 0.88 * DAILY_SALARY
        else:
            target = max(0.62 * DAILY_SALARY, highest_prev_bid + 2.0)
            if tight_supply:
                target = max(target, 0.82 * DAILY_SALARY)
    else:
        if very_tight:
            if highest_prev_bid >= 150 and rich_aggressive >= 2:
                target = 0.22 * DAILY_SALARY
            else:
                target = max(0.52 * DAILY_SALARY, min(0.86 * DAILY_SALARY, highest_prev_bid + 1.5))
        elif tight_supply:
            if highest_prev_bid >= 150:
                target = 0.30 * DAILY_SALARY
            else:
                target = max(0.42 * DAILY_SALARY, min(0.72 * DAILY_SALARY, avg_prev_bid + 1.0))
        else:
            target = 0.24 * DAILY_SALARY
            if day >= 8:
                target = 0.34 * DAILY_SALARY

    if budget < DAILY_SALARY * 0.75:
        target = min(target, budget * 0.72)
    elif budget < DAILY_SALARY * 1.5:
        target = min(target, budget * 0.82)

    target = max(0.0, min(budget, target))
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps or budget <= 0:
        return 0.0

    # Read yesterday bids from traces for immediate reaction
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate competitive level from yesterday
    if prev_bids:
        top_bid = max(prev_bids)
        second_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else top_bid
    else:
        top_bid = 0.0
        second_bid = 0.0

    # My urgency: if low hp or already missing water, increase bid
    urgency = 0.0
    if hp <= 2.0:
        urgency += 1.0
    if hp <= 4.0:
        urgency += 0.6
    if no_water_days >= 1:
        urgency += 0.7
    if no_water_days >= 2:
        urgency += 0.9

    # Supply factor: in medium, supply likely limits winners; bid more when supply is lower in range
    # Normalize supply within [15,25]
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    # Lower supply => higher need => higher bid
    supply_need = 1.0 - min(1.0, max(0.0, supply_norm))

    # Baseline: aim around 0.55-0.75 of daily salary depending on urgency
    base = DAILY_SALARY * (0.55 + 0.20 * supply_need + 0.15 * min(1.0, urgency))

    # If Cindy-like behavior dominates (very high top bid), don't chase exactly; bid near second+small
    # to avoid overpaying while still competing.
    # Use ratio to detect aggressive opponents.
    aggressive = 1.0 if (top_bid >= DAILY_SALARY * 1.5) else 0.0

    if aggressive > 0.5 and second_bid > 0:
        target = min(budget, max(base, second_bid + 2.0))
    else:
        # Otherwise, slightly undercut top to conserve budget
        if top_bid > 0:
            target = min(budget, max(base, min(top_bid - 1.0, base + 25.0)))
        else:
            target = min(budget, base)

    # Hard caps to avoid bankruptcy
    # If hp is healthy, don't spend too much; if hp is critical, allow up to 0.95 salary.
    if hp >= 7.0 and no_water_days == 0:
        cap = DAILY_SALARY * 0.75
    elif hp >= 5.0:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * 0.95

    bid = min(target, cap, budget)

    # Ensure non-negative float
    if bid < 0:
        bid = 0.0

    return float(bid)

